    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (isPerfectSquare(A[i] + A[j])) {
                dp[i][j] = dp[i][j - 1] + dp[i + 1][j];
            }
        }
    }
    return dp[0][n - 1];
}

