public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[i2] * 2, Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = min;
        if (min == uglyNumbers[i2] * 2) i2++;
        if (min == uglyNumbers[i3] * 3) i3++;
        if (min == uglyNumbers[i5] * 5) i5++;
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int currentLength = 0;
    char currentChar = s.charAt(0);
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            if (currentLength > energy) {
                energy = currentLength;
            }
            currentLength = 1;
            currentChar = s.charAt(i);
        }
    }
    if (currentLength > energy) {
        energy = currentLength;
    }
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

